insert into public.clubs (slug, name, category, tagline, description, logo_url, accent_color, website_url, instagram_url, linkedin_url, faculty_advisor, founded_year)
values
('aerobots', 'Aerobots Club', 'Technical', 'Skybound Curiosity: Where Minds Soar in Aviation Elegance!', 'Aerobots is NHCE''s aviation and robotics club. It runs workshops and seminars, trains members in beginner and advanced robotics, hosts hackathons, and drives research initiatives in robotics and technology.', '/logos/aerobots.jpg', '#0284c7', 'https://newhorizonindia.edu/co-curricular/aerobots/', 'https://www.instagram.com/aerobots_nhce', null, null, null),
('business-and-information-technology', 'Business & Information Technology Club', 'Business', 'Empowering futures at the intersection of business and technology.', 'The BIT Club organises educational workshops and seminars, hackathons and tech challenges, skill-development workshops (coding, data analysis, digital marketing, design thinking, project management), tech talks and webinars, and networking events linking students, faculty, alumni and industry.', '/logos/business-and-information-technology.png', '#0f766e', 'https://newhorizonindia.edu/co-curricular/business-and-information-technology/', 'https://www.instagram.com/nhce_bitclub/', 'https://www.linkedin.com/in/bit-club-80a0592a0', null, null),
('cybersecurity-and-ethical-hacking', 'Cybersecurity & Ethical Hacking Club', 'Technical', 'Detect. Decode. Decipher.', 'The Cybersecurity and Ethical Hacking club of NHCE is a community of enthusiasts fostering knowledge and skills in cybersecurity: educating members about threats and best practices, promoting ethical hacking and responsible use of hacking skills, and raising awareness of cybercrime and cybersecurity law.', '/logos/cybersecurity-and-ethical-hacking.jpg', '#6d28d9', 'https://newhorizonindia.edu/co-curricular/cybersecurity-and-ethical-hacking/', null, null, null, null),
('data-analytics', 'Data Analytics Club', 'Technical', 'Transforming Data Desert into Oasis of Insights', 'A student-run club that equips students with the analytical tools needed in today''s business scenario, giving technical and theoretical know-how of in-demand analytics tools so NHCE students stand out.', '/logos/data-analytics.jpg', '#ea580c', 'https://newhorizonindia.edu/co-curricular/data-analytics/', 'https://www.instagram.com/data_analytics_club_nhce', null, null, null),
('ed-start-up', 'Entrepreneurship Development & Start-Up Club', 'Business', 'Empowering Students to Innovate, Create, and Thrive in the Entrepreneurial World.', 'Through awareness, support and resources, the club fosters a culture of entrepreneurship at NHCE, promoting sustainable solutions and igniting the passion for business.', '/logos/ed-start-up.png', '#4338ca', 'https://newhorizonindia.edu/co-curricular/ed-start-up/', 'https://www.instagram.com/ed_startupclub', null, null, null),
('emsys', 'EmSys Nex Gen', 'Technical', 'Unlocking the power of connectivity with embedded systems: where technology meets possibility.', 'EmSys Nex Gen is NHCE''s embedded systems club — a community for students who want to build with microcontrollers, sensors and connected devices.', null, '#ca8a04', 'https://newhorizonindia.edu/co-curricular/emsys/', 'https://www.instagram.com/emsysnexgen.nhce', null, null, null),
('evolve-ai', 'Evolve.AI', 'Technical', 'Explore. Empower. Evolve.', 'Evolve.AI is NHCE''s hub for cutting-edge AI events, activities and community — workshops, seminars, hackathons and competitions that foster creativity, collaboration and curiosity across all departments.', '/logos/evolve-ai.png', '#dc2626', 'https://newhorizonindia.edu/co-curricular/evolve-ai/', 'https://www.instagram.com/evolve.ai_nhce/', null, null, null),
('foss', 'FOSS Club', 'Technical', 'Empower, Create, Contribute', 'Empower your skills, unleash creativity, and contribute to a community of growth and innovation. Freshers and seasoned coders are equally welcome.', '/logos/foss.jpg', '#1d4ed8', 'https://newhorizonindia.edu/co-curricular/foss/', 'https://www.instagram.com/_nhce_foss_club_official_', null, null, null),
('green-energy', 'Green Energy Club', 'Sustainability', 'Let''s empower a sustainable future together', 'The Green Energy Club spreads awareness of sustainable technology and its impact on the environment, economy and society; advances education and research in green technologies and renewable energy; and champions projects and startups — through events, workshops, outreach, R&D and policy engagement.', '/logos/green-energy.jpg', '#65a30d', 'https://newhorizonindia.edu/co-curricular/green-energy/', null, null, null, null),
('healthxcel', 'HealthXcel Club', 'Health', 'Engineering Precision. Healing Vision.', 'HealthXcel is a nexus for people passionate about intertwining engineering and medical science: interdisciplinary collaboration, workshops with healthcare institutions, hands-on research and project-based learning, and networking and publication in healthcare engineering.', '/logos/healthxcel.png', '#0d9488', 'https://newhorizonindia.edu/co-curricular/healthxcel/', 'https://www.instagram.com/healthxcel.nhce/', null, null, null),
('innovation', 'Innovation Club', 'Science & Innovation', 'Innovate. Ideate. Implement.', 'The Innovation Club ignites passion, inspires collaboration and drives technological advancement by giving students a platform to explore, connect and showcase innovative projects that cross academic boundaries.', '/logos/innovation.png', '#d97706', 'https://newhorizonindia.edu/co-curricular/innovation/', 'https://www.instagram.com/innovation.club.nhce', 'https://www.linkedin.com/in/innovation-club-nhce/', null, null),
('mobile-app-development', 'Mobile App Development Club', 'Technical', 'A community built on creativity and learning.', 'MAD Club advocates for the education and creation of modern apps in the mobile space through small teams building real projects: hands-on workshops, hackathons and design sprints, with 150+ participants at every event. Active since 2023.', '/logos/mobile-app-development.jpg', '#a21caf', 'https://newhorizonindia.edu/co-curricular/mobile-app-development/', 'https://www.instagram.com/md_club_nhce/', null, null, 2023),
('robohorizon', 'RoboHorizon Club', 'Technical', 'Igniting Robotic Dreams.', 'RoboHorizon arranges workshops, seminars and industrial visits, trains members in basic and advanced robots, and promotes all-round development in robotics engineering.', '/logos/robohorizon.jpg', '#0369a1', 'https://newhorizonindia.edu/co-curricular/robohorizon/', 'https://www.instagram.com/robohorizon.nhce', null, null, null),
('stem', 'STEM Club', 'Science & Innovation', 'Science • Technology • Engineering • Mathematics', 'The STEM Club at New Horizon College of Engineering is a creative hub where innovation meets exploration — workshops, hackathons, idea-blitz competitions, coding games and maker projects, plus mega-events like Synapse ''25 and signature formats like Builder''s Asylum, Traffic 360 and E-Wasted.', '/logos/stem.png', '#0891b2', 'https://newhorizonindia.edu/co-curricular/stem/', 'https://www.instagram.com/stemclubnhce', 'http://www.linkedin.com/in/stem-club-nhce-34aa14397', 'Dr. Rakesh C (Co-Curricular Club Head)', null),
('tech-forge-club', 'Tech Forge Club', 'Technical', 'Driven by Tech »  Code ✦ Innovate ✦ Automate', 'Tech Forge is NHCE''s co-curricular technical club (est. 2022): events, hackathons, seminars and workshops across AI & ML, web & app, cybersecurity, cloud, IoT & robotics — plus outreach like Helping Hands and A Day of Giving, and the flagship fest TECHFORGE ''26.', '/logos/tech-forge-club.jpg', '#ea580c', 'https://newhorizonindia.edu/co-curricular/tech-forge-club/', 'https://www.instagram.com/techforge_nhce', null, null, 2022)
